"""ClaimSource that reads claims pre-generated by scripts/generate_claims.py."""
import json
from typing import Iterator

from common.datasets.base import LabeledClaim
from common.paths import claims_dir


class JsonlClaimSource:
    """Reads data/claims/<dataset>/<split>.jsonl. One JSON object per line:
    {"claim", "label", "gold_triple", ...extra metadata ignored here}.
    """

    def __init__(self, dataset: str):
        self.dataset = dataset

    def claims(self, split: str) -> Iterator[LabeledClaim]:
        path = claims_dir(self.dataset) / f"{split}.jsonl"
        if not path.exists():
            raise FileNotFoundError(f"{path} not found. Run scripts/generate_claims.py first.")
        with open(path, encoding="utf-8") as f:
            for line in f:
                if line.strip():
                    d = json.loads(line)
                    h, r, t = d["gold_triple"]
                    yield LabeledClaim(claim=d["claim"], label=d["label"], gold_triple=(h, r, t))
